/*
 * A093109  Numbers n such that the Zsigmondy number Zs(n,5,1) differs from
 *          the n-th cyclotomic polynomial evaluated at 5.
 * https://oeis.org/A093109
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   numbers n of the form ord_5(p) * p^k where p is a prime ≠ 5 and
 *            k > 0. The sequence is generated by a lazy min‑heap over all
 *            such values, producing the terms in increasing order
 * Range:     u8 none, u16 none, u32 n <= 51, u64 n <= 51, u128 n <= 51,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* ---------- auxiliary types ---------- */
typedef struct {
    seq_t val;   /* current value of ord_5(p) * p^k   */
    seq_t ord;   /* ord_5(p)                         */
    uint64_t p;  /* the prime                        */
} node_t;

/* ---------- global / static data ---------- */
static bool  init_done   = false;   /* one‑time initialization flag   */
static size_t prime_cnt  = 0;       /* number of primes generated     */
static uint64_t *prime_tab = NULL;  /* array of primes                */

static node_t *heap      = NULL;    /* min‑heap of active nodes       */
static size_t  heap_sz   = 0;
static size_t  heap_cap  = 0;

static seq_t *seq      = NULL;      /* array holding the sequence     */
static size_t  seq_sz  = 0;
static size_t  seq_cap = 0;

/* ---------- utility: modular exponentiation (uint64_t) ---------- */
static uint64_t powmod64(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1;
    uint64_t b = base % mod;
    while (exp) {
        if (exp & 1U)
            result = ( (unsigned __int128) result * b ) % mod;
        b = ( (unsigned __int128) b * b ) % mod;
        exp >>= 1U;
    }
    return result;
}

/* ---------- compute ord_5(p) for a prime p (p != 5) ---------- */
static seq_t order_5_prime(uint64_t p)
{
    if (p == 2) return (seq_t)1;       /* ord_5(2) = 1 */
    uint64_t n = p - 1;
    /* factor n using the pre‑computed prime table */
    uint64_t factors[64];
    size_t   fac_cnt = 0;
    uint64_t m = n;
    for (size_t i = 0; i < prime_cnt && prime_tab[i] * prime_tab[i] <= m; ++i) {
        uint64_t q = prime_tab[i];
        if (m % q == 0) {
            factors[fac_cnt++] = q;
            while (m % q == 0)  m /= q;
        }
    }
    if (m > 1) factors[fac_cnt++] = m;   /* remaining prime factor */

    uint64_t ord = n;
    for (size_t i = 0; i < fac_cnt; ++i) {
        uint64_t q = factors[i];
        while (ord % q == 0 && powmod64(5, ord / q, p) == 1)
            ord /= q;
    }
    return (seq_t)ord;
}

/* ---------- min‑heap operations ---------- */
static void heap_push(node_t v)
{
    size_t i = heap_sz++;
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent].val <= v.val) break;
        heap[i] = heap[parent];
        i = parent;
    }
    heap[i] = v;
}

static node_t heap_pop(void)
{
    node_t min = heap[0];
    node_t last = heap[--heap_sz];
    size_t i = 0;
    while (true) {
        size_t left = (i << 1) + 1;
        if (left >= heap_sz) break;
        size_t right = left + 1;
        size_t smallest = left;
        if (right < heap_sz && heap[right].val < heap[left].val)
            smallest = right;
        if (heap[smallest].val >= last.val) break;
        heap[i] = heap[smallest];
        i = smallest;
    }
    heap[i] = last;
    return min;
}

/* ---------- initialization routine ---------- */
static void init(void)
{
    if (init_done) return;

    /* --- generate primes up to LIMIT --- */
    const uint64_t LIMIT = 200000ULL;   /* sufficient for n up to ~10⁴ */
    bool *is_comp = (bool*)calloc(LIMIT + 1, sizeof(bool));
    prime_tab = (uint64_t*)malloc((LIMIT / 10 + 10) * sizeof(uint64_t));
    prime_cnt = 0;
    for (uint64_t i = 2; i <= LIMIT; ++i) {
        if (!is_comp[i]) {
            if (prime_cnt == (LIMIT / 10 + 10))
                prime_tab = (uint64_t*)realloc(prime_tab,
                                    (prime_cnt + 1000) * sizeof(uint64_t));
            prime_tab[prime_cnt++] = i;
            if (i * i <= LIMIT) {
                for (uint64_t j = i * i; j <= LIMIT; j += i)
                    is_comp[j] = true;
            }
        }
    }
    free(is_comp);

    /* --- build the heap with one element per prime (except 5) --- */
    heap_cap = prime_cnt + 1;  /* capacity for heap nodes */
    heap = (node_t*)malloc(heap_cap * sizeof(node_t));
    heap_sz = 0;
    for (size_t i = 0; i < prime_cnt; ++i) {
        uint64_t p = prime_tab[i];
        if (p == 5) continue;             /* 5 is excluded */
        seq_t ord = order_5_prime(p);
        node_t v = { ord * (seq_t)p, ord, p };
        heap_push(v);
    }

    /* --- sequence array --- */
    seq_cap = 256;
    seq = (seq_t*)malloc(seq_cap * sizeof(seq_t));
    seq_sz = 0;

    init_done = true;
}

/* ---------- the required function ---------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;      /* out of bounds, not used */
    init();

    /* extend the sequence until we have n terms */
    while (seq_sz < (size_t)n) {
        node_t cur = heap_pop();
        seq_t val = cur.val;
        if (seq_sz == seq_cap) {
            seq_cap <<= 1;
            seq = (seq_t*)realloc(seq, seq_cap * sizeof(seq_t));
        }
        seq[seq_sz++] = val;

        /* push the next multiple for the same prime */
        seq_t next = val * (seq_t)cur.p;
        node_t nxt = { next, cur.ord, cur.p };
        heap_push(nxt);
    }

    return seq[(size_t)n - 1];
}
